import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";import{M as i}from"./chunks/assets.DjpLsfX1.js";var a=JSON.parse(`{"title":"User Access Levels in the System","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/03-user-roles.md","filePath":"02-consumer/03-user-roles.md"}`),o={name:`02-consumer/03-user-roles.md`};function s(n,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[e(`<h1 id="user-access-levels-in-the-system" tabindex="-1">User Access Levels in the System <a class="header-anchor" href="#user-access-levels-in-the-system" aria-label="Permalink to “User Access Levels in the System”">​</a></h1><p>User access is managed through an Access Control List (ACL) system.</p><p>However, users are divided into three general levels:</p><ul><li>Developer</li><li>Admin</li><li>User</li></ul><p>No user is allowed to edit the access level of someone above their own level. For example, an administrator cannot modify a developer&#39;s role.</p><h1 id="developer" tabindex="-1">Developer <a class="header-anchor" href="#developer" aria-label="Permalink to “Developer”">​</a></h1><p>The developer has 100% full access to the website. Therefore, do not grant developer access to any administrator, including the senior administrator.</p><h1 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to “Admin”">​</a></h1><p>Administrators generally have extensive privileges, except for a few highly sensitive areas that they do not need access to:</p><ul><li>Changes to the website&#39;s language</li><li>Website appearance and color scheme settings</li><li>Website template design</li></ul><p>All other permissions are available to administrators.</p><h1 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to “User”">​</a></h1><p>A regular user whose access level is defined by administrators. All permissions available in the system&#39;s access control functionality can be edited.</p><p>After creating a user, you can configure their permissions using a form similar to the following:</p><p><img src="`+i+`" alt="acl.png" width="955" height="948"></p>`,15)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};